PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS chain_config_snapshot (id INTEGER PRIMARY KEY, chain_id INTEGER NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tokens (address TEXT PRIMARY KEY, chain_id INTEGER NOT NULL, symbol TEXT NOT NULL, decimals INTEGER NOT NULL CHECK(decimals BETWEEN 0 AND 255), canonical INTEGER NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pools (address TEXT PRIMARY KEY, chain_id INTEGER NOT NULL, token0 TEXT NOT NULL, token1 TEXT NOT NULL, fee INTEGER NOT NULL, state_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS positions (id TEXT PRIMARY KEY, token_id TEXT NOT NULL UNIQUE, pool_address TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS position_deposits (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), tx_hash TEXT NOT NULL, log_index INTEGER NOT NULL, token0_raw TEXT NOT NULL, token1_raw TEXT NOT NULL, prices_json TEXT NOT NULL, block_number TEXT NOT NULL, block_timestamp TEXT NOT NULL, UNIQUE(tx_hash,log_index));
CREATE TABLE IF NOT EXISTS liquidity_changes (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), tx_hash TEXT NOT NULL, log_index INTEGER NOT NULL, kind TEXT NOT NULL, token0_raw TEXT NOT NULL, token1_raw TEXT NOT NULL, UNIQUE(tx_hash,log_index));
CREATE TABLE IF NOT EXISTS collections (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), tx_hash TEXT NOT NULL, log_index INTEGER NOT NULL, token0_raw TEXT NOT NULL, token1_raw TEXT NOT NULL, principal0_raw TEXT NOT NULL, principal1_raw TEXT NOT NULL, fee0_raw TEXT NOT NULL, fee1_raw TEXT NOT NULL, UNIQUE(tx_hash,log_index));
CREATE TABLE IF NOT EXISTS fee_claims (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), collection_id TEXT, token0_raw TEXT NOT NULL, token1_raw TEXT NOT NULL, claim_prices_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS principal_withdrawals (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), collection_id TEXT, token0_raw TEXT NOT NULL, token1_raw TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS swaps (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), tx_hash TEXT NOT NULL, log_index INTEGER NOT NULL, execution_cost_usd REAL NOT NULL DEFAULT 0, UNIQUE(tx_hash,log_index));
CREATE TABLE IF NOT EXISTS gas_costs (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), tx_hash TEXT NOT NULL, native_raw TEXT NOT NULL, usd_value REAL, UNIQUE(tx_hash));
CREATE TABLE IF NOT EXISTS price_snapshots (id TEXT PRIMARY KEY, token_address TEXT NOT NULL, block_number TEXT NOT NULL, price_usd REAL NOT NULL, source TEXT NOT NULL, confidence TEXT NOT NULL, observed_at TEXT NOT NULL, UNIQUE(token_address,block_number,source));
CREATE TABLE IF NOT EXISTS transaction_intents (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transaction_receipts (tx_hash TEXT PRIMARY KEY, intent_id TEXT REFERENCES transaction_intents(id), receipt_json TEXT NOT NULL, reconciled_at TEXT);
CREATE TABLE IF NOT EXISTS pnl_snapshots (id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reconciliation_runs (id TEXT PRIMARY KEY, position_id TEXT REFERENCES positions(id), start_block TEXT, end_block TEXT, status TEXT NOT NULL, details_json TEXT NOT NULL, created_at TEXT NOT NULL);
